static PyObject *py_kong_gbm(PyObject *self, PyObject *args) {
    PyObject *obj;
    if (!PyArg_ParseTuple(args, "O", &obj)) return NULL;
    PyObject *fast = PySequence_Fast(obj, "features must be a sequence");
    if (!fast) return NULL;
    if (PySequence_Fast_GET_SIZE(fast) != 21) {
        Py_DECREF(fast);
        PyErr_SetString(PyExc_ValueError, "21 features");
        return NULL;
    }
    double x[21];
    for (int i = 0; i < 21; i++) {
        x[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(fast, i));
        if (x[i] == -1.0 && PyErr_Occurred()) {
            Py_DECREF(fast);
            return NULL;
        }
    }
    Py_DECREF(fast);
    double s = 0.20177099188229322;
    for (int t = 0; t < 300; t++) {
        int n = KONG_ROOT[t];
        while (!KONG_LEAF[n]) n = x[KONG_FEAT[n]] <= KONG_THR[n] ? KONG_LEFT[n] : KONG_RIGHT[n];
        s += KONG_VAL[n];
    }
    return PyFloat_FromDouble(s);
}

/* The rule line's own race (v2). The runtime's race holds each level's
 * opponents' hazard constant over that level's horizon, counts each live copy
 * as one, and prices a move made at any later draw at its value one draw
 * ahead. Here a profile carries the hazards as vectors over the draws left
 * (h: the race of a wait, q: the step hazards, each before the speed), and a
 * context carries a real weight per tile (the effective live copies of a
 * tile are its weight times its available copies) and a fan multiplier.
 *   V2_ROUND: the hazard before each draw is the vector's at that draw's
 *             level, round by round; else each level's own value, held.
 *   V2_TIMING: a move made at a later draw is priced at the level it is made
 *             at: the wait it reaches scaled by its own race's ratio.
 * With neither flag, unit weights and a multiplier of one it is the runtime's
 * race, in the same arithmetic order (consistency with the runtime). Level
 * D: about to draw with D draws left, no hazard pending; the hazard before
 * the k-th draw after it is the vector's at D - k. */
#define V2_PROFILES 256
#define V2_ROUND 1
#define V2_TIMING 2
#define V2_SPAN 128 /* draws -64..63 */
#define V2_CACHE_BITS 18

typedef struct {
    double h[V2_SPAN], q[V2_SPAN];
    double saved, one_step, far_step, hunt;
    int flags, upgrade, complete, guard;
} v2_profile;

static v2_profile v2_profiles[V2_PROFILES];
static int v2_profile_count;
static race_profile v2_unused_profile;

typedef struct {
    race_ctx x;            /* availability (counts), melds, fallback, speed; x.profile is the v2 profile's id */
    const v2_profile *p;
    double a[NTILES];      /* effective live copies */
    double fanm;           /* fan multiplier */
    uint64_t salt;         /* the memo key's word for the weights, speed and multiplier */
} v2_ctx;

typedef struct {
    uint64_t k[5];
    double value, chance;
} v2_slot;

static v2_slot v2_cache[1 << V2_CACHE_BITS];

typedef struct {
    analysis_row r;
    double copies, value, ukeire; /* effective: winning copies, fan-weighted winning copies, improving copies */
} v2_row;

static int v2_at(int d) { return d < -64 ? 0 : d > 63 ? V2_SPAN - 1 : d + 64; }
static double v2_h(const v2_ctx *v, int d) { return v->p->h[v2_at(d)] * v->x.speed; }
static double v2_q(const v2_ctx *v, int d) { return v->p->q[v2_at(d)] * v->x.speed; }

/* Surviving the opponents before a draw at level d, round by round. */
static double v2_surv(const v2_ctx *v, const double *vec, int d) {
    double s = 1 - vec[v2_at(d)] * v->x.speed;
    return s < 0.0 ? 0.0 : s;
}

/* race_repeat_x under the profile's guard (held hazards). */
static double v2_repeat(const v2_ctx *v, double stay, int draws) {
    if (v->p->guard && draws <= 0) return 0.0;
    return race_repeat(stay, draws);
}

/* lead[j], j < n: reaching the j-th draw after level's first (each failing
 * with keep) and surviving to the draw after it, round by round. */
static int v2_leads(const v2_ctx *v, double keep, int level, int n, double *lead) {
    if (n > 64) n = 64;
    double prod = 1.0;
    for (int j = 0; j < n; j++) {
        double s = v2_surv(v, v->p->q, level - j - 1);
        lead[j] = prod * s;
        prod *= keep * s;
    }
    return n < 0 ? 0 : n;
}

/* R[m], m = 0..L (L < 64): a wait of chance c raced from level m, round by round. */
static void v2_reps(const v2_ctx *v, double chance, int L, double *R) {
    R[0] = 0.0;
    for (int m = 1; m <= L; m++) R[m] = 1 + (1 - chance) * v2_surv(v, v->p->h, m - 1) * R[m - 1];
}

/* A wait valued at level L, reached j draws later: its value's ratio. */
static double v2_rho(const double *R, int L, int j) {
    if (j == 0) return 1.0;
    if (L - j < 1 || R[L] <= 0.0) return 0.0;
    return R[L - j] / R[L];
}

static double v2_race(const v2_ctx *v, double chance, double gain, int draws) {
    if (!(v->p->flags & V2_ROUND)) return gain * v2_repeat(v, (1 - chance) * (1 - v2_h(v, draws)), draws);
    if (v->p->guard && draws <= 0) return 0.0;
    double total = 0.0, prod = 1.0;
    for (int j = 0; j < draws && j < 64; j++) {
        total += prod;
        prod *= (1 - chance) * v2_surv(v, v->p->h, draws - j - 1);
    }
    return gain * total;
}

static void v2_sums(const v2_ctx *v, v2_row *w) {
    double copies = 0.0, value = 0.0, ukeire = 0.0;
    for (int i = 0; i < w->r.n_wins; i++) {
        double a = v->a[w->r.wins[i]];
        copies += a;
        value += a * (double)w->r.fans[i];
    }
    for (int i = 0; i < w->r.n_improving; i++) ukeire += v->a[w->r.improving[i]];
    w->copies = copies;
    w->value = value;
    w->ukeire = ukeire;
}

static int v2_row_at(v2_ctx *v, const int *c, int opened, uint64_t k0, uint64_t k1, int raw, int chain, int piao,
                     v2_row *w) {
    if (race_row(&v->x, c, opened, k0, k1, raw, chain, piao, &w->r) < 0) return -1;
    v2_sums(v, w);
    return 0;
}

static void v2_wait_row(v2_ctx *v, const int *c, int opened, uint64_t k0, uint64_t k1, int chain, int piao, v2_row *w) {
    race_wait_row(&v->x, c, opened, k0, k1, chain, piao, &w->r);
    v2_sums(v, w);
}

static int v2_analysis(v2_ctx *v, const int *c, v2_row *w) {
    if (race_analysis_at(&v->x, c, v->x.opened, 0, 0, &w->r) < 0) return -1;
    v2_sums(v, w);
    return 0;
}

/* baotou_fans over the effective copies. */
static void v2_baotou_fans(const v2_ctx *v, const int *c, int opened, int chain, int piao, double *copies,
                           double *value) {
    int odd = 0, luxury = 0;
    for (int i = 0; i < WHITE; i++) {
        odd += c[i] % 2;
        if (c[i] == 4) luxury++;
    }
    double total = 0.0, weighted = 0.0;
    for (int t = 0; t < NTILES; t++) {
        if (v->x.avail[t] <= 0 || c[t] >= 4) continue;
        int o = odd, l = luxury, whites = c[WHITE];
        if (t == WHITE) whites++;
        else {
            o += c[t] % 2 ? -1 : 1;
            if (c[t] == 3) l++;
        }
        long fan = 1;
        if (opened == 0 && o <= whites) {
            if (whites == 4 && o == 0) l++;
            fan = 1L << (1 + l);
        }
        if (chain > 0) fan *= 1L << chain;
        if (whites + piao == 4) fan *= 2;
        fan *= 2;
        total += v->a[t];
        weighted += v->a[t] * (double)fan;
    }
    *copies = total;
    *value = weighted;
}

static int v2_key(const v2_ctx *v, uint64_t k0, uint64_t k1, int kind, int chain, int piao, int draws, int options,
                  uint64_t *k) {
    if (!race_key_of(&v->x, k0, k1, kind, chain, piao, draws, options, k)) return 0;
    k[4] = v->salt;
    return 1;
}

static v2_slot *v2_slot_of(const uint64_t *k) {
    uint64_t h = (k[0] * 0x9E3779B97F4A7C15ULL) ^ (k[1] * 0xC2B2AE3D27D4EB4FULL) ^ (k[2] * 0xD6E8FEB86659FD93ULL)
               ^ (k[3] * 0x94D049BB133111EBULL) ^ (k[4] * 0xBF58476D1CE4E5B9ULL);
    h ^= h >> 31;
    return &v2_cache[h >> (64 - V2_CACHE_BITS)];
}

static void v2_store(v2_slot *slot, const uint64_t *key, double value, double chance) {
    if (!slot) return;
    memcpy(slot->k, key, sizeof(slot->k));
    slot->value = value;
    slot->chance = chance;
}

/* kong_draw_value over the effective copies. */
static int v2_kong_draw(v2_ctx *v, int *c, int tile, double *out) {
    v2_row row;
    int opened = v->x.opened + 1;
    uint64_t k0, k1;
    c[tile] -= 3;
    shanten_key(c, opened, &k0, &k1);
    int raw = shanten_keyed(k0, k1, c, opened), rc = 0;
    if (raw > 0) row.r.distance = raw;
    else rc = v2_row_at(v, c, opened, k0, k1, raw, 1, 0, &row);
    c[tile] += 3;
    if (rc < 0) return -1;
    *out = row.r.distance > 0 ? 0.0 : (v->fanm * row.value + v->p->saved * row.copies) / v->x.unseen;
    return 0;
}

static int v2_waiting_at(v2_ctx *v, int *c, uint64_t k0, uint64_t k1, int chain, int piao, int draws, int options,
                         double *out, double *chance_out);

/* The trade option of a wait one step ahead (race_reshape_gain_at). */
static int v2_reshape_gain_at(v2_ctx *v, int *c, uint64_t k0, uint64_t k1, int draws, double *out) {
    if (draws < 2) {
        *out = 0.0;
        return 0;
    }
    uint64_t key[5];
    int keyed = v2_key(v, k0, k1, 2, 0, 0, draws, 0, key);
    v2_slot *slot = keyed ? v2_slot_of(key) : NULL;
    if (slot && !memcmp(slot->k, key, sizeof(key))) {
        *out = slot->value;
        return 0;
    }
    const v2_profile *p = v->p;
    const int *avail = v->x.avail;
    const double *a = v->a;
    int opened = v->x.opened, round = p->flags & V2_ROUND, timing = p->flags & V2_TIMING;
    double unseen = v->x.unseen, q = v2_q(v, draws);
    v2_row row, r;
    if (v2_row_at(v, c, opened, k0, k1, shanten_keyed(k0, k1, c, opened), 0, 0, &row) < 0) return -1;
    int wins[NTILES] = {0};
    for (int i = 0; i < row.r.n_wins; i++) wins[row.r.wins[i]] = 1;
    double own = row.copies / unseen;
    double stay = v2_race(v, own, (v->fanm * row.value + p->saved * row.copies) / unseen, draws - 1);
    uint64_t after[NTILES];
    int exact = race_swaps(c, opened, k0, k1, after);
    double gain = 0.0, reach = 0.0, tbest[NTILES], tch[NTILES];
    int traded[NTILES] = {0};
    for (int tile = 0; tile < NTILES; tile++) {
        if (wins[tile] || avail[tile] <= 0 || c[tile] >= 4) continue;
        uint64_t d0, d1, drops = after[tile] & ~(1ULL << tile);
        shanten_key_draw(k0, k1, tile, &d0, &d1);
        c[tile]++;
        double best = stay, bch = own;
        for (int drop = 0; drops >> drop; drop++) {
            if (!(drops >> drop & 1)) continue;
            c[drop]--;
            uint64_t r0, r1;
            race_key_drop(d0, d1, drop, &r0, &r1);
            if (exact || shanten_keyed(r0, r1, c, opened) <= 0) {
                v2_wait_row(v, c, opened, r0, r1, 0, 0, &r);
                double ch = r.copies / unseen;
                double val = v2_race(v, ch, (v->fanm * r.value + p->saved * r.copies) / unseen, draws - 1);
                if (val > best) {
                    best = val;
                    bch = ch;
                }
            }
            c[drop]++;
        }
        c[tile]--;
        if (best > stay) {
            gain += a[tile] * (best - stay);
            reach += a[tile];
            traded[tile] = 1;
            tbest[tile] = best;
            tch[tile] = bch;
        }
    }
    double result;
    if (!round) {
        double survive = (1 - q) * (1 - (row.copies + reach) / unseen);
        result = (1 - q) * gain / unseen * v2_repeat(v, survive, draws - 1);
    } else {
        double lead[64], tot[64], R[64], Rs[64];
        int n = v2_leads(v, 1 - (row.copies + reach) / unseen, draws, draws - 1, lead);
        int L = draws - 1 < 63 ? draws - 1 : 63;
        for (int j = 0; j < n; j++) tot[j] = gain;
        if (timing && n > 0) {
            v2_reps(v, own, L, Rs);
            for (int j = 0; j < n; j++) tot[j] = 0.0;
            for (int tile = 0; tile < NTILES; tile++) {
                if (!traded[tile]) continue;
                v2_reps(v, tch[tile], L, R);
                for (int j = 0; j < n; j++) {
                    double g = tbest[tile] * v2_rho(R, L, j) - stay * v2_rho(Rs, L, j);
                    if (g > 0.0) tot[j] += a[tile] * g;
                }
            }
        }
        result = 0.0;
        for (int j = 0; j < n; j++) result += lead[j] * tot[j] / unseen;
    }
    v2_store(slot, key, result, 0.0);
    *out = result;
    return 0;
}

/* waiting_value (race_waiting_at); chance_out: the chance its race runs at. */
static int v2_waiting_at(v2_ctx *v, int *c, uint64_t k0, uint64_t k1, int chain, int piao, int draws, int options,
                         double *out, double *chance_out) {
    uint64_t key[5];
    int keyed = v2_key(v, k0, k1, 0, chain, piao, draws, options, key);
    v2_slot *slot = keyed ? v2_slot_of(key) : NULL;
    if (slot && !memcmp(slot->k, key, sizeof(key))) {
        *out = slot->value;
        if (chance_out) *chance_out = slot->chance;
        return 0;
    }
    const v2_profile *p = v->p;
    const int *avail = v->x.avail;
    const double *a = v->a;
    int opened = v->x.opened, round = p->flags & V2_ROUND, timing = p->flags & V2_TIMING;
    int L = draws - 1 < 63 ? draws - 1 : 63;
    double unseen = v->x.unseen, result, chance, q = v2_q(v, draws), m = v->fanm;
    v2_row row;
    if (c[WHITE] && race_baotou_keyed(k0, k1, c, opened)) {
        double copies, fan;
        v2_baotou_fans(v, c, opened, chain, piao, &copies, &fan);
        chance = copies / unseen;
        result = v2_race(v, chance, (m * fan + p->saved * copies) / unseen, draws);
    } else {
        int raw = shanten_keyed(k0, k1, c, opened);
        if (v2_row_at(v, c, opened, k0, k1, raw, chain, piao, &row) < 0) return -1;
        if (row.r.distance <= 0) {
            double copies = row.copies;
            double gain = m * row.value + p->saved * copies;
            chance = copies / unseen;
            if (!c[WHITE] && p->complete) {
                int has_fan[NTILES] = {0};
                long fan_white = 0;
                for (int i = 0; i < row.r.n_wins; i++) {
                    has_fan[row.r.wins[i]] = 1;
                    if (row.r.wins[i] == WHITE) fan_white = row.r.fans[i];
                }
                double extra = 0.0, best = 0.0, bch = 0.0;
                int white = 0;
                if (avail[WHITE] > 0 && has_fan[WHITE]) {
                    upgrade_ctx up;
                    upgrade_prepare(c, opened, k0, k1, &up);
                    uint64_t drops = upgrade_drops_of(&up, c, WHITE), d0, d1;
                    shanten_key_draw(k0, k1, WHITE, &d0, &d1);
                    int any = 0;
                    c[WHITE]++;
                    for (int drop = 0; drops; drop++, drops >>= 1) {
                        if (!(drops & 1)) continue;
                        uint64_t r0, r1;
                        race_key_drop(d0, d1, drop, &r0, &r1);
                        c[drop]--;
                        double value, ch;
                        int rc = v2_waiting_at(v, c, r0, r1, 0, 0, draws - 1, 0, &value, &ch);
                        c[drop]++;
                        if (rc < 0) {
                            c[WHITE]--;
                            return -1;
                        }
                        if (!any || value > best) {
                            best = value;
                            bch = ch;
                        }
                        any = 1;
                    }
                    c[WHITE]--;
                    white = 1;
                    if (!round) {
                        double w = (1 - q) * best - m * (double)fan_white - p->saved;
                        extra += a[WHITE] * (w > 0.0 ? w : 0.0);
                    }
                }
                int held[NTILES], order[NTILES], n = 0;
                for (int t = 0; t < NTILES; t++)
                    if (c[t]) held[n++] = t;
                n = py_set_order(held, n, order);
                for (int i = 0; i < n; i++) {
                    int tile = order[i];
                    if (c[tile] == 3 && avail[tile] > 0 && !has_fan[tile]) {
                        double kong;
                        if (v2_kong_draw(v, c, tile, &kong) < 0) return -1;
                        extra += a[tile] * kong;
                    }
                }
                if (!round) {
                    result = v2_race(v, chance, (gain + extra) / unseen, draws);
                } else if (p->guard && draws <= 0) {
                    result = 0.0;
                } else {
                    double R[64], total = 0.0, prod = 1.0;
                    if (white && timing) v2_reps(v, bch, L > 0 ? L : 0, R);
                    for (int j = 0; j < draws && j < 64; j++) {
                        double e = extra;
                        if (white) {
                            double b = timing ? best * v2_rho(R, L, j) : best;
                            double w = v2_surv(v, p->q, draws - j - 1) * b - m * (double)fan_white - p->saved;
                            e += a[WHITE] * (w > 0.0 ? w : 0.0);
                        }
                        total += prod * (gain + e) / unseen;
                        prod *= (1 - chance) * v2_surv(v, p->h, draws - j - 1);
                    }
                    result = total;
                }
            } else if (!c[WHITE] || !p->upgrade) {
                result = v2_race(v, chance, gain / unseen, draws);
            } else {
                /* A draw that frees a white lets a discard turn the wait into baotou. */
                long fan_of[NTILES];
                int has_fan[NTILES] = {0};
                for (int i = 0; i < row.r.n_wins; i++) {
                    has_fan[row.r.wins[i]] = 1;
                    fan_of[row.r.wins[i]] = row.r.fans[i];
                }
                double total = 0.0, reach = 0.0, tbest[NTILES], tch[NTILES];
                uint64_t upgrades[NTILES];
                race_upgrade_drops(c, opened, k0, k1, upgrades);
                for (int tile = 0; tile < NTILES; tile++) {
                    tbest[tile] = 0.0;
                    tch[tile] = 0.0;
                    if (avail[tile] <= 0 || c[tile] >= 4) continue;
                    double best = 0.0, bch = 0.0;
                    uint64_t drops = upgrades[tile], d0, d1;
                    shanten_key_draw(k0, k1, tile, &d0, &d1);
                    c[tile]++;
                    for (int drop = 0; drops; drop++, drops >>= 1) {
                        if (!(drops & 1)) continue;
                        uint64_t r0, r1;
                        race_key_drop(d0, d1, drop, &r0, &r1);
                        c[drop]--;
                        double value, ch;
                        if (v2_waiting_at(v, c, r0, r1, 0, 0, draws - 1, 0, &value, &ch) < 0) {
                            c[drop]++;
                            c[tile]--;
                            return -1;
                        }
                        if (value > best) {
                            best = value;
                            bch = ch;
                        }
                        c[drop]++;
                    }
                    c[tile]--;
                    tbest[tile] = best;
                    tch[tile] = bch;
                    if (has_fan[tile]) {
                        double win = m * (double)fan_of[tile] + p->saved, hunt = (1 - q) * best * p->hunt;
                        total += a[tile] * (hunt > win ? hunt : win);
                    } else if (best != 0.0) {
                        total += a[tile] * (1 - q) * best * p->hunt;
                        reach += a[tile];
                    }
                }
                chance = (copies + reach) / unseen;
                if (!round) {
                    double stay = (1 - v2_h(v, draws)) * (1 - (copies + reach) / unseen);
                    result = total / unseen * v2_repeat(v, stay, draws);
                } else if (p->guard && draws <= 0) {
                    result = 0.0;
                } else {
                    int n = draws < 64 ? draws : 64;
                    double tot[64] = {0}, R[64];
                    for (int tile = 0; tile < NTILES; tile++) {
                        if (avail[tile] <= 0 || c[tile] >= 4) continue;
                        double best = tbest[tile];
                        if (!has_fan[tile] && best == 0.0) continue;
                        if (timing) v2_reps(v, tch[tile], L > 0 ? L : 0, R);
                        for (int j = 0; j < n; j++) {
                            double b = timing ? best * v2_rho(R, L, j) : best;
                            double hunt = v2_surv(v, p->q, draws - j - 1) * b * p->hunt;
                            if (has_fan[tile]) {
                                double win = m * (double)fan_of[tile] + p->saved;
                                tot[j] += a[tile] * (hunt > win ? hunt : win);
                            } else {
                                tot[j] += a[tile] * hunt;
                            }
                        }
                    }
                    double prod = 1.0;
                    result = 0.0;
                    for (int j = 0; j < n; j++) {
                        result += prod * tot[j] / unseen;
                        prod *= (1 - chance) * v2_surv(v, p->h, draws - j - 1);
                    }
                }
            }
        } else {
            double u = row.ukeire / unseen;
            chance = u;
            if (row.r.distance == 1) {
                uint64_t after[NTILES];
                if (draws > 1) race_swaps(c, opened, k0, k1, after);
                double weighted = 0.0, tot[64] = {0}, R[64];
                int n = draws - 1 < 64 ? draws - 1 : 64;
                for (int i = 0; i < row.r.n_improving; i++) {
                    int tile = row.r.improving[i];
                    uint64_t d0, d1, r0, r1;
                    shanten_key_draw(k0, k1, tile, &d0, &d1);
                    c[tile]++;
                    double best = 0.0, bch = 0.0;
                    int target = -1;
                    if (draws > 1) {
                        uint64_t drops = raw <= 0 ? after[tile] | 1ULL << tile : after[tile] & ~(1ULL << tile);
                        for (int drop = 0; drops >> drop; drop++) {
                            if (!(drops >> drop & 1)) continue;
                            c[drop]--;
                            race_key_drop(d0, d1, drop, &r0, &r1);
                            if (shanten_keyed(r0, r1, c, opened) <= 0) {
                                double value, ch;
                                if (v2_waiting_at(v, c, r0, r1, 0, 0, draws - 1, 0, &value, &ch) < 0) {
                                    c[drop]++;
                                    c[tile]--;
                                    return -1;
                                }
                                if (value > best) {
                                    best = value;
                                    bch = ch;
                                    target = drop;
                                }
                            }
                            c[drop]++;
                        }
                    }
                    if (options && target >= 0 && chain == 0) {
                        double g;
                        c[target]--;
                        race_key_drop(d0, d1, target, &r0, &r1);
                        int rc = v2_reshape_gain_at(v, c, r0, r1, draws - 1, &g);
                        c[target]++;
                        if (rc < 0) {
                            c[tile]--;
                            return -1;
                        }
                        best += g;
                    }
                    c[tile]--;
                    weighted += a[tile] * best;
                    if (round && best != 0.0) {
                        if (timing) v2_reps(v, bch, L > 0 ? L : 0, R);
                        for (int j = 0; j < n; j++) tot[j] += a[tile] * (timing ? best * v2_rho(R, L, j) : best);
                    }
                }
                if (!round) {
                    double stay = (1 - u) * (1 - q);
                    result = (1 - q) * (weighted / unseen) * v2_repeat(v, stay, draws - 1);
                } else {
                    double lead[64];
                    n = v2_leads(v, 1 - u, draws, n, lead);
                    result = 0.0;
                    for (int j = 0; j < n; j++) result += lead[j] * tot[j] / unseen;
                }
            } else if (!round) {
                double step = (1 - q) * u * v2_repeat(v, (1 - u) * (1 - q), draws - row.r.distance);
                result = step * p->one_step * pow(p->far_step, (double)(row.r.distance - 2));
            } else {
                double lead[64], step = 0.0;
                int n = v2_leads(v, 1 - u, draws, draws - row.r.distance, lead);
                for (int j = 0; j < n; j++) step += lead[j];
                result = step * u * p->one_step * pow(p->far_step, (double)(row.r.distance - 2));
            }
        }
    }
    v2_store(slot, key, result, chance);
    *out = result;
    if (chance_out) *chance_out = chance;
    return 0;
}

static int v2_waiting(v2_ctx *v, int *c, int chain, int piao, int draws, int options, double *out) {
    uint64_t k0, k1;
    shanten_key(c, v->x.opened, &k0, &k1);
    return v2_waiting_at(v, c, k0, k1, chain, piao, draws, options, out, NULL);
}

/* reshaped_value (race_reshaped). */
static int v2_reshaped(v2_ctx *v, int *c, int draws, int options, double *out) {
    uint64_t key[5], k0, k1;
    int opened = v->x.opened;
    shanten_key(c, opened, &k0, &k1);
    int keyed = v2_key(v, k0, k1, 1, 0, 0, draws, options, key);
    v2_slot *slot = keyed ? v2_slot_of(key) : NULL;
    if (slot && !memcmp(slot->k, key, sizeof(key))) {
        *out = slot->value;
        return 0;
    }
    const v2_profile *p = v->p;
    const int *avail = v->x.avail;
    const double *a = v->a;
    int round = p->flags & V2_ROUND, timing = p->flags & V2_TIMING;
    double unseen = v->x.unseen, value, result, q = v2_q(v, draws);
    int distance = shanten_keyed(k0, k1, c, opened);
    if (distance > 0) {
        if (v2_waiting_at(v, c, k0, k1, 0, 0, draws, options && distance == 1, &result, NULL) < 0) return -1;
    } else if (v2_waiting_at(v, c, k0, k1, 0, 0, draws, 0, &value, NULL) < 0) {
        return -1;
    } else if (draws < 2) {
        result = value;
    } else {
        v2_row row;
        if (v2_row_at(v, c, opened, k0, k1, distance, 0, 0, &row) < 0) return -1;
        int wins[NTILES] = {0};
        for (int i = 0; i < row.r.n_wins; i++) wins[row.r.wins[i]] = 1;
        double stay, own;
        if (v2_waiting_at(v, c, k0, k1, 0, 0, draws - 1, 0, &stay, &own) < 0) return -1;
        uint64_t after[NTILES];
        race_swaps(c, opened, k0, k1, after);
        double gain = 0.0, reach = 0.0, tbest[NTILES], tch[NTILES];
        int traded[NTILES] = {0};
        for (int tile = 0; tile < NTILES; tile++) {
            if (wins[tile] || avail[tile] <= 0 || c[tile] >= 4) continue;
            uint64_t d0, d1, drops = after[tile] & ~(1ULL << tile);
            shanten_key_draw(k0, k1, tile, &d0, &d1);
            c[tile]++;
            double best = stay, bch = own;
            for (int drop = 0; drops >> drop; drop++) {
                if (!(drops >> drop & 1)) continue;
                c[drop]--;
                uint64_t r0, r1;
                race_key_drop(d0, d1, drop, &r0, &r1);
                if (shanten_keyed(r0, r1, c, opened) <= 0) {
                    double w, ch;
                    if (v2_waiting_at(v, c, r0, r1, 0, 0, draws - 1, 0, &w, &ch) < 0) {
                        c[drop]++;
                        c[tile]--;
                        return -1;
                    }
                    if (w > best) {
                        best = w;
                        bch = ch;
                    }
                }
                c[drop]++;
            }
            c[tile]--;
            if (best > stay) {
                gain += a[tile] * (best - stay);
                reach += a[tile];
                traded[tile] = 1;
                tbest[tile] = best;
                tch[tile] = bch;
            }
        }
        if (!round) {
            double survive = (1 - q) * (1 - (row.copies + reach) / unseen);
            result = value + (1 - q) * gain / unseen * v2_repeat(v, survive, draws - 1);
        } else {
            double lead[64], tot[64], R[64], Rs[64];
            int n = v2_leads(v, 1 - (row.copies + reach) / unseen, draws, draws - 1, lead);
            int L = draws - 1 < 63 ? draws - 1 : 63;
            for (int j = 0; j < n; j++) tot[j] = gain;
            if (timing && n > 0) {
                v2_reps(v, own, L, Rs);
                for (int j = 0; j < n; j++) tot[j] = 0.0;
                for (int tile = 0; tile < NTILES; tile++) {
                    if (!traded[tile]) continue;
                    v2_reps(v, tch[tile], L, R);
                    for (int j = 0; j < n; j++) {
                        double g = tbest[tile] * v2_rho(R, L, j) - stay * v2_rho(Rs, L, j);
                        if (g > 0.0) tot[j] += a[tile] * g;
                    }
                }
            }
            result = value;
            for (int j = 0; j < n; j++) result += lead[j] * tot[j] / unseen;
        }
    }
    v2_store(slot, key, result, 0.0);
    *out = result;
    return 0;
}

static uint64_t v2_mix(uint64_t h, double d) {
    uint64_t b;
    memcpy(&b, &d, sizeof(b));
    h = (h ^ b) * 0xBF58476D1CE4E5B9ULL;
    return h ^ (h >> 27);
}

/* Parse (hand, opened, available, profile, fallback, speed, weights, fanm) into a context. */
static int v2_setup(v2_ctx *v, int *c, PyObject *hand, int opened, PyObject *available, int profile,
                    PyObject *fallback, double speed, PyObject *weights, double fanm) {
    if (profile < 0 || profile >= v2_profile_count) {
        PyErr_SetString(PyExc_ValueError, "unknown v2 race profile");
        return -1;
    }
    if (opened < 0 || opened > 4) {
        PyErr_SetString(PyExc_ValueError, "open_melds must be 0..4");
        return -1;
    }
    if (meld_tables() < 0) return -1;
    memset(v, 0, sizeof(*v));
    PyObject *seq = PySequence_Fast(hand, "hand must be a sequence");
    if (!seq) return -1;
    memset(c, 0, NTILES * sizeof(int));
    Py_ssize_t size = PySequence_Fast_GET_SIZE(seq);
    for (Py_ssize_t i = 0; i < size; i++) {
        long tile = PyLong_AsLong(PySequence_Fast_GET_ITEM(seq, i));
        if (tile < 0 || tile >= NTILES || ++c[tile] > 4) {
            Py_DECREF(seq);
            if (!PyErr_Occurred()) PyErr_SetString(PyExc_ValueError, "invalid hand");
            return -1;
        }
    }
    Py_DECREF(seq);
    if (size != 13 - 3 * opened) {
        PyErr_SetString(PyExc_ValueError, "race valuation expects a waiting hand");
        return -1;
    }
    race_ctx *x = &v->x;
    if (parse_vector(available, x->avail, 1000000, "available") < 0) return -1;
    double w[NTILES];
    for (int t = 0; t < NTILES; t++) w[t] = 1.0;
    if (weights != Py_None) {
        PyObject *ws = PySequence_Fast(weights, "weights must be a sequence of 34 floats");
        if (!ws) return -1;
        if (PySequence_Fast_GET_SIZE(ws) != NTILES) {
            Py_DECREF(ws);
            PyErr_SetString(PyExc_ValueError, "weights must have 34 entries");
            return -1;
        }
        for (int t = 0; t < NTILES; t++) w[t] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(ws, t));
        Py_DECREF(ws);
        if (PyErr_Occurred()) return -1;
    }
    long unseen = 0;
    x->keyed = 1;
    for (int t = 0; t < NTILES; t++) {
        unseen += x->avail[t];
        if (x->avail[t] < 0 || x->avail[t] > 7) x->keyed = 0;
        else if (t < 21) x->a0 |= (uint64_t)x->avail[t] << (3 * t);
        else x->a1 |= (uint64_t)x->avail[t] << (3 * (t - 21));
        v->a[t] = x->avail[t] > 0 ? w[t] * (double)x->avail[t] : 0.0;
    }
    x->unseen = unseen < 1 ? 1 : (int)unseen;
    x->p = &v2_unused_profile;
    x->profile = profile;
    x->speed = speed;
    x->speed_key = 0;
    x->available = available;
    x->fallback = fallback;
    x->opened = opened;
    x->size = (int)size;
    v->p = &v2_profiles[profile];
    v->fanm = fanm;
    uint64_t h = 0x9E3779B97F4A7C15ULL;
    for (int t = 0; t < NTILES; t++) h = v2_mix(h, v->a[t]);
    h = v2_mix(h, speed);
    v->salt = v2_mix(h, fanm);
    return 0;
}

static int v2_vector(PyObject *obj, double *out) {
    PyObject *s = PySequence_Fast(obj, "expected a sequence of 128 floats");
    if (!s) return -1;
    if (PySequence_Fast_GET_SIZE(s) != V2_SPAN) {
        Py_DECREF(s);
        PyErr_SetString(PyExc_ValueError, "hazard vectors cover draws -64..63 (128 entries)");
        return -1;
    }
    for (int i = 0; i < V2_SPAN; i++) out[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(s, i));
    Py_DECREF(s);
    return PyErr_Occurred() ? -1 : 0;
}

/* v2_profile(h, q, flags, saved, one_step, far_step, hunt, upgrade, complete, guard) -> id */
static PyObject *py_v2_profile(PyObject *self, PyObject *args) {
    v2_profile p;
    PyObject *h, *q;
    memset(&p, 0, sizeof(p));
    if (!PyArg_ParseTuple(args, "OOiddddppp", &h, &q, &p.flags, &p.saved, &p.one_step, &p.far_step, &p.hunt,
                          &p.upgrade, &p.complete, &p.guard))
        return NULL;
    if (v2_vector(h, p.h) < 0 || v2_vector(q, p.q) < 0) return NULL;
    for (int i = 0; i < v2_profile_count; i++)
        if (!memcmp(&v2_profiles[i], &p, sizeof(p))) return PyLong_FromLong(i);
    if (v2_profile_count >= V2_PROFILES) {
        PyErr_SetString(PyExc_ValueError, "too many v2 race profiles");
        return NULL;
    }
    v2_profiles[v2_profile_count] = p;
    return PyLong_FromLong(v2_profile_count++);
}

/* v2_waiting(hand, opened, available, chain, piao, draws, profile, fallback, options, speed, weights, fanm) */
static PyObject *py_v2_waiting(PyObject *self, PyObject *args) {
    PyObject *hand, *available, *fallback, *weights;
    int opened, chain, piao, draws, profile, options, c[NTILES];
    double speed, fanm;
    if (!PyArg_ParseTuple(args, "OiOiiiiOpdOd", &hand, &opened, &available, &chain, &piao, &draws, &profile,
                          &fallback, &options, &speed, &weights, &fanm))
        return NULL;
    v2_ctx v;
    if (v2_setup(&v, c, hand, opened, available, profile, fallback, speed, weights, fanm) < 0) return NULL;
    double out;
    if (v2_waiting(&v, c, chain, piao, draws, options, &out) < 0) return NULL;
    return PyFloat_FromDouble(out);
}

/* v2_reshaped(hand, opened, available, draws, profile, fallback, options, speed, weights, fanm) */
static PyObject *py_v2_reshaped(PyObject *self, PyObject *args) {
    PyObject *hand, *available, *fallback, *weights;
    int opened, draws, profile, options, c[NTILES];
    double speed, fanm;
    if (!PyArg_ParseTuple(args, "OiOiiOpdOd", &hand, &opened, &available, &draws, &profile, &fallback, &options,
                          &speed, &weights, &fanm))
        return NULL;
    v2_ctx v;
    if (v2_setup(&v, c, hand, opened, available, profile, fallback, speed, weights, fanm) < 0) return NULL;
    double out;
    if (v2_reshaped(&v, c, draws, options, &out) < 0) return NULL;
    return PyFloat_FromDouble(out);
}

/* The feed rates' scale by stage (k_feed), set once from Python. */
static double V2_FEED[3] = {1.0, 1.0, 1.0};

static PyObject *py_v2_feed_scale(PyObject *self, PyObject *args) {
    if (!PyArg_ParseTuple(args, "ddd", &V2_FEED[0], &V2_FEED[1], &V2_FEED[2])) return NULL;
    Py_RETURN_NONE;
}

/* called_value over the v2 race. */
static int v2_called_value(v2_ctx *y, int *c, int a, int b, int far, int draws, double q, double *out) {
    c[a]--;
    c[b]--;
    double best = 0.0;
    int rc = 0, near = 99, dist[NTILES];
    for (int d = 0; d < NTILES; d++) {
        if (!c[d]) continue;
        c[d]--;
        dist[d] = shanten_raw(c, y->x.opened);
        c[d]++;
        if (dist[d] < near) near = dist[d];
    }
    for (int d = 0; d < NTILES && rc == 0; d++) {
        if (!c[d] || dist[d] != near) continue;
        c[d]--;
        double val;
        rc = far ? v2_reshaped(y, c, draws, 0, &val) : v2_waiting(y, c, 0, 0, draws, 0, &val);
        double shape = 0.0;
        if (rc == 0) rc = shape_bonus(&y->x, c, &shape);
        c[d]++;
        if (rc == 0) {
            val = (1 - q) * val + shape;
            if (val > best) best = val;
        }
    }
    c[a]++;
    c[b]++;
    *out = best;
    return rc;
}

/* v2_call_option(hand, opened, available, draws, stage, chis, profile, fallback, weight, speed, weights, fanm) */
static PyObject *py_v2_call_option(PyObject *self, PyObject *args) {
    PyObject *hand, *available, *fallback, *weights;
    int opened, draws, stage, chis, profile, c[NTILES];
    double weight, speed, fanm;
    if (!PyArg_ParseTuple(args, "OiOiiiiOddOd", &hand, &opened, &available, &draws, &stage, &chis, &profile,
                          &fallback, &weight, &speed, &weights, &fanm))
        return NULL;
    if (stage < 0 || stage > 2) {
        PyErr_SetString(PyExc_ValueError, "stage must be 0..2");
        return NULL;
    }
    if (opened >= 4) return PyFloat_FromDouble(0.0);
    v2_ctx v;
    if (v2_setup(&v, c, hand, opened, available, profile, fallback, speed, weights, fanm) < 0) return NULL;
    v2_row row;
    if (v2_analysis(&v, c, &row) < 0) return NULL;
    if (row.r.distance < 1) return PyFloat_FromDouble(0.0);
    int far = row.r.distance >= 2;
    double q = v2_q(&v, draws);
    double stay_value;
    if (v2_reshaped(&v, c, draws, 0, &stay_value) < 0) return NULL;
    double stay_shape;
    if (shape_bonus(&v.x, c, &stay_shape) < 0) return NULL;
    stay_value += stay_shape;
    v2_ctx y = v;
    y.x.opened = opened + 1;
    y.x.size = v.x.size - 3;
    double unseen = (double)v.x.unseen, gain = 0.0;
    for (int t = 0; t < WHITE; t++) {
        if (!v.x.avail[t]) continue;
        double best_gain = 0.0, best_rate = 0.0, val;
        if (c[t] >= 2) {
            if (v2_called_value(&y, c, t, t, far, draws, q, &val) < 0) return NULL;
            if (val - stay_value > best_gain) {
                best_gain = val - stay_value;
                best_rate = FEED_PENG[stage][tile_kind(t)] * V2_FEED[stage];
            }
        }
        if (t < 27 && chis < 2) {
            const int pairs[3][2] = {{t - 2, t - 1}, {t - 1, t + 1}, {t + 1, t + 2}};
            for (int k = 0; k < 3; k++) {
                int a = pairs[k][0], b = pairs[k][1];
                if (a < 0 || b >= 27 || a / 9 != t / 9 || b / 9 != t / 9 || !c[a] || !c[b]) continue;
                if (v2_called_value(&y, c, a, b, far, draws, q, &val) < 0) return NULL;
                if (val - stay_value > best_gain) {
                    best_gain = val - stay_value;
                    best_rate = FEED_CHI[stage][tile_kind(t)] * V2_FEED[stage];
                }
            }
        }
        gain += best_rate * v.a[t] / unseen * best_gain;
    }
    double u = row.ukeire / unseen, rounds;
    if (!(v.p->flags & V2_ROUND)) {
        double stay = (1 - u) * (1 - q);
        rounds = stay < 1 ? (1 - pow(stay, (double)draws)) / (1 - stay) : (double)draws;
    } else {
        double prod = 1.0;
        rounds = 0.0;
        for (int j = 0; j < draws && j < 64; j++) {
            rounds += prod;
            prod *= (1 - u) * v2_surv(&v, v.p->q, draws - j - 1);
        }
    }
    return PyFloat_FromDouble(weight * gain * rounds);
}

/* route_of / route_value over the effective copies (the weights in the memo key). */
typedef struct {
    uint64_t k0, k1, a0, a1, salt;
    double value, ukeire;
} v2_route_slot;

static v2_route_slot v2_route_cache[1 << ROUTE_BITS];

static double v2_route_value(v2_ctx *v, int *c) {
    int opened = v->x.opened;
    const int *avail = v->x.avail;
    const draw_slot *table = draw_distances(c, opened);
    if (table->distance != 1) return 0.0;
    uint64_t improving = 0;
    for (int t = 0; t < NTILES; t++)
        if (avail[t] > 0 && c[t] < 4 && table->draw[t] < 1) improving |= (uint64_t)1 << t;
    uint64_t k0, k1, after[NTILES];
    shanten_key(c, opened, &k0, &k1);
    race_swaps(c, opened, k0, k1, after);
    double total = 0.0, weighted = 0.0;
    for (int tile = 0; tile < NTILES; tile++) {
        if (!(improving >> tile & 1)) continue;
        uint64_t d0, d1;
        shanten_key_draw(k0, k1, tile, &d0, &d1);
        c[tile]++;
        double best = 0.0;
        uint64_t drops = after[tile];
        for (int drop = 0; drops >> drop; drop++) {
            if (!(drops >> drop & 1) || !c[drop]) continue;
            uint64_t r0, r1;
            race_key_drop(d0, d1, drop, &r0, &r1);
            c[drop]--;
            if (shanten_keyed(r0, r1, c, opened) <= 0) {
                v2_row row;
                v2_wait_row(v, c, opened, r0, r1, 0, 0, &row);
                if (row.value > best) best = row.value;
            }
            c[drop]++;
        }
        c[tile]--;
        total += v->a[tile];
        weighted += v->a[tile] * best;
    }
    return total ? weighted / total : 0.0;
}

static double v2_route_of(v2_ctx *v, int *c, double *ukeire) {
    uint64_t k0, k1;
    shanten_key(c, v->x.opened, &k0, &k1);
    k1 ^= (uint64_t)v->x.opened << 60;
    uint64_t h = (k0 * 0x9E3779B97F4A7C15ULL) ^ (k1 * 0xC2B2AE3D27D4EB4FULL) ^ (v->x.a0 * 0x165667B19E3779F9ULL)
               ^ v->x.a1 ^ (v->salt * 0xD6E8FEB86659FD93ULL);
    v2_route_slot *slot = &v2_route_cache[(h >> 20) & ((1 << ROUTE_BITS) - 1)];
    if (v->x.keyed && slot->k0 == k0 && slot->k1 == k1 && slot->a0 == v->x.a0 && slot->a1 == v->x.a1
        && slot->salt == v->salt) {
        *ukeire = slot->ukeire;
        return slot->value;
    }
    const draw_slot *table = draw_distances(c, v->x.opened);
    double u = 0.0;
    for (int t = 0; t < NTILES; t++)
        if (v->x.avail[t] > 0 && c[t] < 4 && table->draw[t] < table->distance) u += v->a[t];
    double val = v2_route_value(v, c);
    if (v->x.keyed) {
        slot->k0 = k0; slot->k1 = k1; slot->a0 = v->x.a0; slot->a1 = v->x.a1; slot->salt = v->salt;
        slot->value = val; slot->ukeire = u;
    }
    *ukeire = u;
    return val;
}

/* v2_reshape_gain(hand, opened, available, draws, profile, fallback, speed, weights, fanm) */
static PyObject *py_v2_reshape_gain(PyObject *self, PyObject *args) {
    PyObject *hand, *available, *fallback, *weights;
    int opened, draws, profile, c[NTILES], held[NTILES];
    double speed, fanm;
    if (!PyArg_ParseTuple(args, "OiOiiOdOd", &hand, &opened, &available, &draws, &profile, &fallback, &speed,
                          &weights, &fanm))
        return NULL;
    v2_ctx v;
    if (v2_setup(&v, c, hand, opened, available, profile, fallback, speed, weights, fanm) < 0) return NULL;
    v2_row row;
    if (v2_analysis(&v, c, &row) < 0) return NULL;
    if (row.r.distance != 1 || draws < 3) return PyFloat_FromDouble(0.0);
    int improving[NTILES] = {0};
    for (int i = 0; i < row.r.n_improving; i++) improving[row.r.improving[i]] = 1;
    double ukeire = row.ukeire;
    double stay;
    if (v2_waiting(&v, c, 0, 0, draws - 1, 0, &stay) < 0) return NULL;
    memcpy(held, c, sizeof(held));
    double own;
    double floor_ = ukeire * v2_route_of(&v, c, &own);
    double gain = 0.0, reach = 0.0;
    for (int tile = 0; tile < NTILES; tile++) {
        if (improving[tile] || v.x.avail[tile] <= 0 || c[tile] >= 4) continue;
        int near = c[tile] > 0;
        if (tile < 27)
            for (int u = tile - 2; u <= tile + 2 && !near; u++)
                near = u >= 0 && u < 27 && u / 9 == tile / 9 && c[u] > 0;
        if (!near) continue;
        c[tile]++;
        int pick = -1;
        double lead = floor_;
        for (int drop = 0; drop < NTILES; drop++) {
            if (!held[drop] || drop == tile) continue;
            c[drop]--;
            if (shanten_raw(c, opened) == 1) {
                double alt;
                double estimate = v2_route_of(&v, c, &alt);
                if (estimate > 0) {
                    estimate *= alt;
                    if (estimate > lead) {
                        pick = drop;
                        lead = estimate;
                    }
                }
            }
            c[drop]++;
        }
        double best = stay;
        if (pick >= 0) {
            c[pick]--;
            double val;
            int rc = v2_waiting(&v, c, 0, 0, draws - 1, 0, &val);
            c[pick]++;
            if (rc < 0) return NULL;
            if (val > best) best = val;
        }
        c[tile]--;
        if (best > stay) {
            gain += v.a[tile] * (best - stay);
            reach += v.a[tile];
        }
    }
    double unseen = (double)v.x.unseen, qs = v2_q(&v, draws), result;
    if (!(v.p->flags & V2_ROUND)) {
        double survive = (1 - qs) * (1 - (ukeire + reach) / unseen);
        double rounds = draws - 1 <= 0 ? 0.0 : (1 - pow(survive, (double)(draws - 1))) / (1 - survive);
        result = (1 - qs) * gain / unseen * rounds;
    } else {
        double lead[64];
        int n = v2_leads(&v, 1 - (ukeire + reach) / unseen, draws, draws - 1, lead);
        result = 0.0;
        for (int j = 0; j < n; j++) result += lead[j] * gain / unseen;
    }
    return PyFloat_FromDouble(result);
}

